"""Verified UI122 Brazilian Portuguese RH workspace overlay; production data is never opened."""
from pathlib import Path, PurePosixPath
import base64, hashlib, json, sys, zlib
PARENT_MANIFEST_SHA256 = '06a5e6b85ca3b1e925976405f2f6ea473578501f002d358f155241db7ef81584'
TARGET_MANIFEST_SHA256 = '974b21cf4267564f46bc504908daed03365fdbd221c1747321f3a4688820a3ae'
TARGET_VARIANT = 'workspace-ui122-permissions-pt-br-2026-10-17'
FILES = {'UI_PATCH.json': {'before': '382a1598b1cb0e0eb48d3786b1cf3a14f3dc1f9976463b3983e1ae9406af23ea', 'after': '5d77908ebfe8d5a819dd4ed81b9035779cde4a7b864ce07458167278df10af51', 'bytes': 637, 'payload': ''}, 'app/__init__.py': {'before': 'a586a9007c1ef1254367c10e510b311127a3d0f3b3026eb7271bc48949390a4f', 'after': 'c7ead8e4f99f2bc2f5a3558acad8cdd4ac0d10c744b0f18340f5bb7eb8e8046e', 'bytes': 84, 'payload': 'eNoFwcEKgCAMANC7XzF2qouQde07OsrSUaMxQU3o73sPEQ8arGIPaEmkcL8nTMoXpQ8ydQLJbF26cIPKncQ4zx4RXYyDa5NiMcIOuPh18yGg+wG9shrT'}, 'app/static/browser_admin.js': {'before': '7129d0824d0b41cdcccc30e741f8ed6169d8ae8a48ac20a22630982f719b3350', 'after': '662e99109df8de7b1d1e1c3aaaa5d5be9e79e9afee6b9ec4fe956c97d4b44884', 'bytes': 30529, 'payload': ''}, 'app/static/locale_pt_br.js': {'before': '2add84302531e0fcfa7bddc2569553c6a926f9faab3673a9b62bde991745e654', 'after': 'f0824e213422b21b2fdb9a4ba800a19c7d6661ea68abf8105ed961592209a6a5', 'bytes': 199089, 'payload': ''}, 'tests/test_admin_permissions_locale_ui122.cjs': {'before': None, 'after': '945c120bd35a92fffe40f88b5cf644c5e91991a52841b75eedc0df9cafb2be19', 'bytes': 7468, 'payload': ''}}

def apply(destination: Path):
    destination = Path(destination)
    if destination.is_symlink() or not destination.is_dir():
        raise ValueError('UI122 destination must be an existing directory without a root symlink.')
    destination = destination.resolve()
    manifest_path = destination/'RELEASE_FILES.json'
    if manifest_path.is_symlink() or not manifest_path.is_file():
        raise ValueError('UI122 manifest must be a regular file without a symlink.')

    def resource_path(name):
        relative = PurePosixPath(name)
        if relative.is_absolute() or not relative.parts or '..' in relative.parts or name!=relative.as_posix() or chr(92) in name:
            raise ValueError('Unsafe UI122 resource path.')
        path = destination.joinpath(*relative.parts)
        current = path
        while current != destination:
            if current.is_symlink():
                raise ValueError('Symlink in UI122 resource path: '+name)
            current = current.parent
        return path

    raw = manifest_path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != PARENT_MANIFEST_SHA256:
        raise ValueError('UI122 requires the exact UI121 manifest. Do not deploy.')
    manifest = json.loads(raw)
    for name,digest in manifest['files'].items():
        path = resource_path(name)
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=digest:
            raise ValueError('UI122 parent resource mismatch: '+name)
    prepared = {}
    for name,record in FILES.items():
        path = resource_path(name)
        if record['before'] is None:
            if path.exists() or name in manifest['files']:
                raise ValueError('UI122 new resource already exists: '+name)
        elif manifest['files'].get(name)!=record['before']:
            raise ValueError('UI122 parent file mismatch: '+name)
        dec=zlib.decompressobj()
        data=dec.decompress(base64.b64decode(record['payload'],validate=True),record['bytes']+1)
        if dec.unconsumed_tail: raise ValueError('Oversized UI122 payload.')
        data+=dec.flush()
        if not dec.eof or dec.unused_data or len(data)!=record['bytes'] or hashlib.sha256(data).hexdigest()!=record['after']:
            raise ValueError('UI122 payload integrity failure: '+name)
        prepared[name]=data
    # Validate the complete target before the first mutation, including a bad
    # target digest or internally inconsistent generated overlay metadata.
    composed = dict(manifest)
    composed['files'] = dict(manifest['files'])
    for name in prepared:
        composed['files'][name] = FILES[name]['after']
    composed['files'] = dict(sorted(composed['files'].items()))
    composed['variant'] = TARGET_VARIANT
    result=(json.dumps(composed,indent=2)+'\n').encode()
    if hashlib.sha256(result).hexdigest()!=TARGET_MANIFEST_SHA256:
        raise ValueError('UI122 manifest composition mismatch.')
    for name,data in prepared.items():
        path=resource_path(name)
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(data)
    manifest_path.write_bytes(result)
    manifest = composed
    for name,digest in manifest['files'].items():
        if hashlib.sha256((destination/name).read_bytes()).hexdigest()!=digest:
            raise ValueError('Derived UI122 resource mismatch: '+name)

if __name__=='__main__':
    apply(Path(sys.argv[1]))
    print('Applied Workspace UI122: Brazilian Portuguese RH workspace; company data retained.')
